const paths=['src/utils/ai/openrouter/embeddings.ai.ts','src/utils/ai/fetch.utils.ts','src/utils/ai/constants.ts','src/utils/ai/openrouter/embeddings.ai.rs','src/utils/ai/openrouter/language_detection.rs','src/utils/ai/fetch.utils.rs','src/utils/ai/constants.rs','src/utils/ai/openrouter/app_attribution.util.rs','src/utils/js_unicode.rs','src/utils/js_unicode_data.rs','src/utils/js_string.rs','src/utils/js_compat.rs','src/utils/logger.rs','src/utils/test_http.rs','tests/ai_embeddings.rs','tests/ai_fetch_retry.rs','tests/fixtures/ai_embeddings_reference.cjs','tests/fixtures/openrouter_attribution_source.cjs','tests/support/sha256.rs','Cargo.toml','Cargo.lock','rust-toolchain.toml'];
